                + this._swapCost(ds, round, d.strategicChoice || 0);
        }

        _composite(ds, period, cbamBonus) {
            var s = Math.max(0, Math.min(100, Math.round(
                ds.trajectoryScore * 0.35 +
                (ds.abatementPct || 0) * 0.25 +
                Math.max(0, 100 - ds.totalCarbonCost * 0.8) * 0.20 +
                ds.creditQualityScore * 0.15 +
                Math.max(0, (100 - ds.compliancePenaltyTotal * 10)) * 0.05 +
                cbamBonus
            )));
            // a run that ends above the 2030 ceiling cannot be graded as meeting the target
            if (period >= this.ROUNDS.length && ds.emissions > ds.sbtiTarget) s = Math.min(s, 74);
            return s;
        }

        _tierId(score) {
            if (score >= 90) return 'leader';
            if (score >= 75) return 'credible';
            if (score >= 60) return 'compliance';
            return 'stranded';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    emissions: 1310000,
                    baselineEmissions: 1401000,
                    sbtiTarget: 812580,
                    totalCarbonCost: 0,
                    totalAbatementSpend: 0,
                    implementedMeasures: [],
                    totalAbatementReduction: 0,
                    measureReduction: 0,
                    abatementPct: 0,
                    maxPossibleAbatement: 421000,
                    trajectoryScore: 50,
                    creditQualityScore: 75,
                    complianceStatus: 'green',
                    totalReddCredits: 0,
                    totalBiogasCredits: 0,
                    totalCookstoveCredits: 0,
                    totalAllowancesBanked: 0,
                    allowanceBank: 0,
                    budgetCarry: 0,
                    icpLevel: 0,
                    cbamStrategy: 0,
                    cbamTotalPaid: 0,
                    controversyResponse: 0,
                    boardConcern: false,
                    emissionsHistory: [],
                    costHistory: [],
                    trajectoryHistory: [],
                    qualityHistory: [],
                    abatementPctHistory: [],
                    compliancePenaltyTotal: 0,
                    firstCbamCost: 0,
                    lastResult: null
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    abatementBudget: 0,
                    allowancePurchase: 0,
                    offsetRedd: 0,
                    offsetBiogas: 0,
                    offsetCookstove: 0,
                    strategicChoice: 0
                };
            }
            this._state = state;
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var ds = state.domainState || {};
            var period = state.currentPeriod || 1;
            var done = period > this.ROUNDS.length;
            var round = this._round(period);
            var self = this;
            this._view = { currentPeriod: period, domainState: ds };

            var yearEl = document.getElementById('yearDisplay');
            if (yearEl) yearEl.textContent = '(' + round.year + ')';

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = done ? this._t('brief_done') : this._t('brief' + period);

            var priceEl = document.getElementById('pricePanel');
            if (priceEl) {
                var html = '<b>' + this._t('prices_title') + '</b> ' + this._t('price_brazil') + ': $' + round.brazilPrice + '/t | ' + this._t('price_colombia') + ': $' + round.colombiaPrice + '/t';
                if (round.euEtsPrice > 0) html += ' | EU ETS (CBAM): $' + round.euEtsPrice + '/t';
                html += '<br><b>' + this._t('credits_title') + '</b> REDD+: $' + round.reddPrice + '/t | ' + this._t('price_biogas') + ': $' + round.biogasPrice + '/t | ' + this._t('price_cookstove') + ': $' + round.cookstovePrice + '/t';
                html += '<br><b>' + this._t('year_budget') + '</b> ' + this._usd(round.budget);
                priceEl.innerHTML = done ? '' : html;
            }

            var implemented = ds.implementedMeasures || [];
            var abIn = document.getElementById('abatementBudgetInput');
            if (abIn && !done) abIn.setAttribute('max', String(Math.floor(this._available(ds, round) * 10) / 10));

            var stratPanel = document.getElementById('strategicPanel');
            var stratSelect = document.getElementById('strategicSelect');
            var stratLabel = document.getElementById('strategicLabel');
            if (stratPanel && stratSelect) {
                var kind = done ? null : round.strategic;
                var sig = kind + '|' + this._lang() + '|' + period;
                if (!kind) {
                    stratPanel.style.display = 'none';
                    stratSelect.setAttribute('data-sig', sig);
                } else if (stratSelect.getAttribute('data-sig') !== sig) {
                    var keep = stratSelect.getAttribute('data-sig') && stratSelect.getAttribute('data-sig').split('|')[2] === String(period) ? stratSelect.value : null;
                    var opts = [];
                    if (kind === 'cbam') opts = [['1', 'cbam_opt1'], ['2', 'cbam_opt2'], ['3', 'cbam_opt3'], ['4', 'cbam_opt4']];
                    if (kind === 'icp') opts = [['20', 'icp_opt20'], ['40', 'icp_opt40'], ['70', 'icp_opt70'], ['100', 'icp_opt100']];
                    if (kind === 'controversy') opts = [['1', 'redd_opt1'], ['2', 'redd_opt2'], ['3', 'redd_opt3']];
                    stratPanel.style.display = 'block';
                    if (stratLabel) stratLabel.textContent = this._t('strat_label_' + kind);
                    stratSelect.innerHTML = opts.map(function(o) { return '<option value="' + o[0] + '">' + self._t(o[1]) + '</option>'; }).join('');
                    stratSelect.setAttribute('data-sig', sig);
                    if (keep !== null && keep !== '') { try { stratSelect.value = keep; } catch (e) {} }
                }
            }

            var canvasE = document.getElementById('emissionsChart');
            if (canvasE) {
                canvasE.setAttribute('role', 'img');
                canvasE.setAttribute('aria-label', this._t('chart_emissions_alt', { e: this._num(ds.emissions || 0, 0), t: this._num(ds.sbtiTarget || 812580, 0) }));
            }
            var canvasC = document.getElementById('costChart');
            if (canvasC) {
                canvasC.setAttribute('role', 'img');
                canvasC.setAttribute('aria-label', this._t('chart_cost_alt', { c: this._usd(ds.totalCarbonCost || 0) }));
            }

            this._renderPlan();
            this._renderResult(ds.lastResult || null);
        }

        // live preview of what the entered numbers fund, before the year is submitted
        _renderPlan() {
            var v = this._view;
            if (!v) return;
            var ds = v.domainState || {};
            var period = v.currentPeriod || 1;
            var done = period > this.ROUNDS.length;
            var round = this._round(period);
            var implemented = ds.implementedMeasures || [];
            var d = this._readInputs({});
            var avail = this._available(ds, round);
            var self = this;

            var measHint = document.getElementById('availableMeasuresText');
            if (measHint) {
                if (done) { measHint.textContent = ''; }
                else {
                    var list = [];
                    for (var m = 0; m < this.MEASURES.length; m++) {
                        if (this.MEASURES[m].round <= period && implemented.indexOf(m) === -1) {
                            list.push(this._mname(m) + ' ($' + this._num(this.MEASURES[m].cost, 1) + 'M, ' + this._num(this.MEASURES[m].reduction, 0) + ' tCO2e)');
                        }
                    }
                    var pick = this._pick(period, implemented, d.abatementBudget || 0);
                    var funded = pick.idx.map(function(i) { return self._mname(i); });
                    measHint.innerHTML = this._t('measures_available') + ' ' + (list.length ? list.join('; ') : this._t('none')) + '.<br>'
                        + this._t('measures_rule') + '<br><b>'
                        + (funded.length
                            ? this._t('measures_funded', { list: funded.join(', '), spent: this._usd(pick.spent), cut: this._num(pick.reduction, 0), unused: this._usd(Math.max(0, (d.abatementBudget || 0) - pick.spent)) })
                            : this._t('measures_funded_none', { unused: this._usd(d.abatementBudget || 0) })) + '</b>';
                }
            }

            var allowHint = document.getElementById('allowancePriceText');
            if (allowHint) {
                if (done) { allowHint.textContent = ''; }
                else {
                    var after = implemented.concat(this._pick(period, implemented, d.abatementBudget || 0).idx);
                    var need = this._sbceNeed(round, after);
                    allowHint.innerHTML = this._t('allow_price', { p: round.brazilPrice }) + '<br>'
                        + this._t('allow_position', { ob: this._num(round.complianceObligation, 0), free: this._num(round.freeAllowances, 0), cut: this._num(this._brazilCut(after), 0), need: this._num(need, 0), bank: this._num(ds.allowanceBank || 0, 0) }) + '<br>'
                        + this._t('allow_rule');
                }
            }

            var swapHint = document.getElementById('strategicHintText');
            if (swapHint) {
                var sc = done ? 0 : this._swapCost(ds, round, d.strategicChoice || 0);
                swapHint.textContent = (!done && round.strategic === 'controversy')
                    ? this._t('swap_hint', { held: this._num(ds.totalReddCredits || 0, 0), cost: this._usd(sc) }) : '';
            }

            var budgetEl = document.getElementById('budgetDisplay');
            if (budgetEl) {
                if (done) { budgetEl.textContent = this._t('none'); }
                else {
                    var planned = this._plannedSpend(d, ds, round);
                    budgetEl.textContent = this._t('budget_line', { left: this._usd(avail - planned), avail: this._usd(avail), carry: this._usd(ds.budgetCarry || 0), planned: this._usd(planned) });
                    budgetEl.className = (avail - planned < -0.005) ? 'carbon-sim-over' : '';
                }
            }
        }

        // what happened last year and why: stays on screen until the next submit
        _renderResult(r) {
            var el = document.getElementById('roundResultText');
            var panel = document.getElementById('roundResultPanel');
            if (!el || !panel) return;
            if (!r) { panel.style.display = 'none'; el.innerHTML = ''; return; }
            var self = this;
            var lines = [];
            var names = (r.measures || []).map(function(i) { return self._mname(i); });
            lines.push(names.length
                ? this._t('res_measures', { year: r.year, spent: this._usd(r.abatementSpent), list: names.join(', '), cut: this._num(r.newReduction, 0) })
                : this._t('res_measures_none', { year: r.year }));
            if (r.unused > 0.05) lines.push(this._t('res_unused', { unused: this._usd(r.unused) }));
            if (r.icpCut > 0) lines.push(this._t('res_icp', { p: r.icpLevel, cut: this._num(r.icpCut, 0) }));
            if (r.sbceNeed > 0 || r.allowanceBought > 0) {
                lines.push(r.shortfall > 0
                    ? this._t('res_sbce_short', { need: this._num(r.sbceNeed, 0), cov: this._num(r.sbceNeed - r.shortfall, 0), short: this._num(r.shortfall, 0), pen: this._usd(r.penaltyCost) })
                    : this._t('res_sbce_ok', { need: this._num(r.sbceNeed, 0), bank: this._num(r.bank, 0) }));
            }
            if (r.cbamCost > 0) lines.push(this._t('res_cbam', { cost: this._usd(r.cbamCost), eu: r.euPrice, br: r.brPrice, int: this._num(r.intensity, 2), vol: this._num(r.exportVolume, 0) }));
            if (r.creditsBought > 0) lines.push(this._t(r.period >= 6 ? 'res_credits_final' : 'res_credits', { n: this._num(r.creditsBought, 0), boost: r.offsetBoost }));
            if (r.boardConcernNow) lines.push(this._t('res_board', { share: Math.round(r.reddShare * 100) }));
            lines.push(this._t('res_bill', { bill: this._usd(r.totalRoundCost), carry: this._usd(r.carry) }));
            lines.push(this._t('res_path', { e: this._num(r.emissions, 0), path: this._num(r.targetPath, 0) }));
            panel.style.display = 'block';
            el.innerHTML = '<ul><li>' + lines.join('</li><li>') + '</li></ul>';
        }

        validateDecisions(decisions) {
            this._readInputs(decisions);
            var sim = window.mySimulation;
            var state = sim.state;
            var round = this._round(state.currentPeriod || 1);
            var ds = state.domainState || {};

            if (decisions.abatementBudget < 0 || decisions.allowancePurchase < 0 || decisions.offsetRedd < 0 || decisions.offsetBiogas < 0 || decisions.offsetCookstove < 0) {
                sim.uiManager.showNotification(sim.t('negative_warning'), 'warning');
                return false;
            }
            if (round.strategic && !(decisions.strategicChoice > 0)) {
                sim.uiManager.showNotification(sim.t('strategic_warning'), 'warning');
                return false;
            }
            if (this._plannedSpend(decisions, ds, round) > this._available(ds, round) + 0.005) {
                sim.uiManager.showNotification(sim.t('budget_warning'), 'warning');
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var r = this._computeRound(state);
            return r;
        }

        _computeRound(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod || 1;
            var round = this._round(period);
            var avail = this._available(ds, round);

            // A. abatement: the lump budget funds the cheapest measures per tonne that fit
            var pick = this._pick(period, ds.implementedMeasures, d.abatementBudget);
            for (var i = 0; i < pick.idx.length; i++) ds.implementedMeasures.push(pick.idx[i]);
            ds.measureReduction = (ds.measureReduction || 0) + pick.reduction;
            ds.totalAbatementReduction += pick.reduction;
            ds.totalAbatementSpend = (ds.totalAbatementSpend || 0) + pick.spent;
            ds.emissions = Math.max(0, ds.emissions - pick.reduction);

            // C. voluntary credits, and the 2028 response applied to the REDD+ already held
            var swapCost = 0;
            if (round.strategic === 'controversy') {
                ds.controversyResponse = d.strategicChoice;
                swapCost = this._swapCost(ds, round, d.strategicChoice);
                var held = ds.totalReddCredits || 0;
                if (d.strategicChoice === 2) { ds.totalReddCredits = held * 0.5; ds.totalBiogasCredits += held * 0.5; }
                if (d.strategicChoice === 3) { ds.totalReddCredits = 0; ds.totalBiogasCredits += held * 0.5; ds.totalCookstoveCredits += held * 0.5; }
            }
            var offsetCost = (d.offsetRedd * round.reddPrice + d.offsetBiogas * round.biogasPrice + d.offsetCookstove * round.cookstovePrice) / 1000 + swapCost;
            ds.totalReddCredits += d.offsetRedd;
            ds.totalBiogasCredits += d.offsetBiogas;
            ds.totalCookstoveCredits += d.offsetCookstove;
            var creditsBought = d.offsetRedd + d.offsetBiogas + d.offsetCookstove;

            // B. SBCE: obligation less free allocation less Brazilian reductions; bought allowances
            // cover it, the rest is banked; every uncovered tonne pays one and a half times the price
            var allowanceCost = (d.allowancePurchase * round.brazilPrice) / 1000;
            ds.totalAllowancesBanked += d.allowancePurchase;
            var need = this._sbceNeed(round, ds.implementedMeasures);
            var bank = (ds.allowanceBank || 0) + d.allowancePurchase;
            var used = Math.min(bank, need);
            bank -= used;
            var shortfall = need - used;
            ds.allowanceBank = bank;
            var penaltyCost = shortfall * round.brazilPrice * 1.5 / 1000;
            ds.complianceStatus = (need > 0 && used <= 0) ? 'red' : ((need > 0 && shortfall > need * 0.2 + 0.000001) ? 'amber' : 'green');

            // CBAM on the steel export book; the 2026 response applies from the following year
            var cbamCost = 0, intensity = 1.82, exportVolume = 120000;
            if (round.euEtsPrice > 0) {
                if (ds.implementedMeasures.indexOf(5) !== -1) intensity -= 0.3;
                if (ds.implementedMeasures.indexOf(8) !== -1) intensity -= 0.35;
                if (ds.cbamStrategy === 4) exportVolume = 60000;
                cbamCost = (Math.max(0, (round.euEtsPrice - round.brazilPrice) * intensity) * exportVolume) / 1000000;
                ds.cbamTotalPaid += cbamCost;
            }

            var colombiaTax = (round.colombiaPrice * 89000 + round.colombiaPrice * 178000 * 0.3 + round.colombiaPrice * 142000 * 0.5) / 1000000;

            // the carbon bill: allowances, penalties, credits, CBAM and carbon tax. Abatement capex is tracked apart
            var bill = allowanceCost + offsetCost + cbamCost + colombiaTax + penaltyCost;
            ds.totalCarbonCost += bill;
            // what was requested for abatement and not used returns to the group; only unrequested budget carries over
            var unused = Math.max(0, (d.abatementBudget || 0) - pick.spent);
            ds.budgetCarry = Math.max(0, Math.round((avail - pick.spent - unused - allowanceCost - offsetCost) * 100) / 100);

            if (round.strategic === 'cbam') ds.cbamStrategy = d.strategicChoice;
            if (round.strategic === 'icp') ds.icpLevel = d.strategicChoice;

            var icpCut = 0;
            if (ds.icpLevel >= 70) icpCut = 27500;
            else if (ds.icpLevel >= 40) icpCut = 8000;
            else if (ds.icpLevel >= 20) icpCut = 3000;
            ds.emissions = Math.max(0, ds.emissions - icpCut);
            ds.totalAbatementReduction += icpCut;

            // trajectory: credits lift the internal indicator during the run, never at the 2030 assessment
            var targetPath = ds.baselineEmissions - ((ds.baselineEmissions - ds.sbtiTarget) * (period / 6));
            var deviation = (ds.emissions - targetPath) / ds.baselineEmissions;
            var offsetBoost = period >= this.ROUNDS.length ? 0 : Math.min(20, creditsBought * 1000 / ds.baselineEmissions * 100);
            ds.trajectoryScore = Math.max(0, Math.min(100, Math.round(80 - deviation * 500 + offsetBoost)));

            var totalCredits = ds.totalReddCredits + ds.totalBiogasCredits + ds.totalCookstoveCredits;
            var reddShare = totalCredits > 0 ? ds.totalReddCredits / totalCredits : 0;
            if (totalCredits > 0) {
                var reddQuality = period >= 4 ? 25 : 45;
                ds.creditQualityScore = Math.round((ds.totalReddCredits * reddQuality + ds.totalBiogasCredits * 88 + ds.totalCookstoveCredits * 95) / totalCredits);
            } else {
                ds.creditQualityScore = 75;
            }
            var boardConcernNow = false;
            if (period === 4 && totalCredits > 0 && reddShare > 0.25) {
                boardConcernNow = true;
                ds.boardConcern = true;
                ds.compliancePenaltyTotal += 3;
            }

            ds.abatementPct = Math.round((ds.measureReduction / ds.maxPossibleAbatement) * 100);

            ds.emissionsHistory.push(ds.emissions);
            ds.costHistory.push(Math.round(bill * 10) / 10);
            ds.trajectoryHistory.push(ds.trajectoryScore);
            ds.qualityHistory.push(ds.creditQualityScore);
            ds.abatementPctHistory.push(ds.abatementPct);

            if (ds.complianceStatus === 'amber') ds.compliancePenaltyTotal += 1;
            if (ds.complianceStatus === 'red') ds.compliancePenaltyTotal += 3;
            if (period === 2) ds.firstCbamCost = cbamCost;
            var cbamBonusNow = (period >= 5 && ds.firstCbamCost > 0 && cbamCost < ds.firstCbamCost * 0.6) ? 5 : 0;
            var overallScore = this._composite(ds, period, cbamBonusNow);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore, score: overallScore, tier: this._tierId(overallScore) });

            var r = {
                period: period,
                year: round.year,
                emissions: ds.emissions,
                newReduction: pick.reduction,
                measures: pick.idx.slice(),
                abatementSpent: Math.round(pick.spent * 10) / 10,
                unused: Math.round(unused * 10) / 10,
                allowanceBought: d.allowancePurchase,
                allowanceCost: Math.round(allowanceCost * 10) / 10,
                offsetCost: Math.round(offsetCost * 10) / 10,
                creditsBought: creditsBought,
                offsetBoost: Math.round(offsetBoost),
                cbamCost: Math.round(cbamCost * 10) / 10,
                euPrice: round.euEtsPrice,
                brPrice: round.brazilPrice,
                intensity: intensity,
                exportVolume: exportVolume,
                sbceNeed: Math.round(need),
                shortfall: Math.round(shortfall),
                bank: Math.round(bank),
                penaltyCost: Math.round(penaltyCost * 10) / 10,
                totalRoundCost: Math.round(bill * 10) / 10,
                carbonBillTotal: Math.round(ds.totalCarbonCost * 10) / 10,
                carry: ds.budgetCarry,
                icpLevel: ds.icpLevel,
                icpCut: icpCut,
                targetPath: Math.round(targetPath),
                trajectoryScore: ds.trajectoryScore,
                creditQuality: ds.creditQualityScore,
                reddShare: Math.round(reddShare * 100) / 100,
                boardConcernNow: boardConcernNow,
                boardConcern: !!ds.boardConcern,
                controversyResponse: ds.controversyResponse,
                steelDone: ds.implementedMeasures.indexOf(5) !== -1 || ds.implementedMeasures.indexOf(8) !== -1,
                abatementPct: ds.abatementPct,
                compliance: ds.complianceStatus,
                penaltyCount: ds.compliancePenaltyTotal,
                cbamBonus: cbamBonusNow,
                overallScore: overallScore
            };
            ds.lastResult = r;

            // the framework advances the period after this method returns, so the next screen is period + 1
            this._updateBriefing({ currentPeriod: period + 1, domainState: ds });
            return r;
        }

        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('emissionsDisplay', 'domainState.emissions',
                function(v) { return self._num(v, 0); });
            uiManager.bind('costDisplay', 'domainState.totalCarbonCost',
                function(v) { return self._usd(v); });
            uiManager.bind('trajectoryDisplay', 'domainState.trajectoryScore');
            uiManager.bind('qualityDisplay', 'domainState.creditQualityScore',
                function(v) { return v + '/100'; });
            uiManager.bind('abatementDisplay', 'domainState.abatementPct',
                function(v) { return (v || 0) + '%'; });
            uiManager.bind('complianceDisplay', 'domainState.complianceStatus',
                function(v) {
                    if (v === 'green') return self._t('status_ok');
                    if (v === 'amber') return self._t('status_risk');
                    return self._t('status_fail');
                });
        }

        getChartConfig() {
            return {
                emissionsChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._t('chart_emissions_series'),
                            data: [],
                            borderColor: '#ef6c00',
                            backgroundColor: 'rgba(239,108,0,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2
                        }, {
                            label: this._t('chart_target_series'),
                            data: [],
                            borderColor: '#2e7d32',
                            borderDash: [8, 4],
                            borderWidth: 2,
                            fill: false,
                            tension: 0.2,
                            pointStyle: 'dash'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: this._t('chart_emissions_title') } },
                        scales: { y: { beginAtZero: false, title: { display: true, text: 'tCO2e' } } }
                    }
                },
                costChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._t('chart_cost_series'),
                            data: [],
                            backgroundColor: 'rgba(21,101,192,0.7)',
                            borderColor: '#1565c0',
                            borderWidth: 1
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: this._t('chart_cost_title') } },
                        scales: { y: { beginAtZero: true, title: { display: true, text: '$M' } } }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var eh = ds.emissionsHistory || [];
            var labels = eh.map(function(_, i) { return String(2025 + i); });
            var baseline = ds.baselineEmissions || 1401000;
            var target = ds.sbtiTarget || 812580;
            var targetPath = labels.map(function(_, i) {
                return Math.round(baseline - ((baseline - target) * ((i + 1) / 6)));
            });
            return {
                emissionsChart: { labels: labels, datasets: [{ data: eh }, { data: targetPath }] },
                costChart: { labels: labels, datasets: [{ data: ds.costHistory || [] }] }
            };
        }

        // one reading of the run, used by the verdict, the insights and the turning point
        _readRun(history) {
            var run = { rows: [], flags: [], creditsLate: 0, cbamPaid: 0, penaltyYears: [], deferYears: [], best: null };
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {};
                run.rows.push(r);
                run.cbamPaid += r.cbamCost || 0;
                if ((r.shortfall || 0) > 0) run.penaltyYears.push(r.year);
                if (r.period <= 2 && !(r.abatementSpent > 0) && (r.allowanceBought || 0) > 0) run.deferYears.push(r.year);
                if (r.period >= 5) run.creditsLate += r.creditsBought || 0;
                if (!run.best || (r.newReduction || 0) > (run.best.newReduction || 0)) run.best = r;
            }
            var last = run.rows[run.rows.length - 1] || {};
            run.last = last;
            run.complete = history.length >= this.ROUNDS.length;
            run.missed = run.complete && (last.emissions || 0) > 812580;
            if (run.deferYears.length) run.flags.push({ id: 'defer', year: run.deferYears[0] });
            if (last.icpLevel > 0 && last.icpLevel < 40) run.flags.push({ id: 'icp', year: 2027 });
            if (last.boardConcern) run.flags.push({ id: 'redd', year: 2028 });
            if (run.complete && !last.steelDone) run.flags.push({ id: 'steel', year: 2027 });
            if (run.missed && run.creditsLate > 0) run.flags.push({ id: 'credits', year: 2029 });
            run.flags.sort(function(a, b) { return a.year - b.year; });
            return run;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var run = this._readRun(history);
            var last = run.last;
            var finalScore = last.overallScore || 0;
            var tier = this._tierId(finalScore);
            var gap = (last.emissions || 0) - 812580;

            var insights = [];
            insights.push(gap <= 0
                ? this._t('ins_target_met', { e: this._num(last.emissions, 0), gap: this._num(-gap, 0) })
                : this._t('ins_target_missed', { e: this._num(last.emissions, 0), gap: this._num(gap, 0) }));
            for (var f = 0; f < run.flags.length; f++) {
                var id = run.flags[f].id;
                if (id === 'defer') insights.push(this._t('ins_defer', { years: run.deferYears.join(', ') }));
                if (id === 'icp') insights.push(this._t('ins_icp', { p: last.icpLevel }));
                if (id === 'redd') insights.push(this._t('ins_redd', { q: last.creditQuality }));
                if (id === 'steel') insights.push(this._t('ins_steel', { paid: this._usd(run.cbamPaid) }));
                if (id === 'credits') insights.push(this._t('ins_credits', { n: this._num(run.creditsLate, 0), gap: this._num(gap, 0) }));
            }
            insights.push(this._t('ins_abatement', { pct: last.abatementPct || 0, bill: this._usd(last.carbonBillTotal || 0), cbam: this._usd(run.cbamPaid) }));
            insights.push(run.penaltyYears.length
                ? this._t('ins_sbce_short', { years: run.penaltyYears.join(', ') })
                : this._t('ins_sbce_ok'));
            if (last.cbamBonus > 0) insights.push(this._t('ins_cbam_bonus'));

            var turning = run.flags.length
                ? this._t('turn_' + run.flags[0].id, { year: run.flags[0].year })
                : this._t('turn_best', { year: run.best ? run.best.year : 2025, cut: this._num(run.best ? run.best.newReduction : 0, 0) });

            return {
                finalScore: finalScore,
                overallScore: finalScore,
                totalScore: finalScore,
                score: finalScore,
                composite: finalScore,
                finalEmissions: last.emissions || 0,
                sbtiTarget: 812580,
                targetMet: gap <= 0,
                totalCarbonCost: last.carbonBillTotal || 0,
                abatementProgress: (last.abatementPct || 0) + '%',
                creditQualityAvg: last.creditQuality || 0,
                trajectoryScore: last.trajectoryScore || 0,
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: this._t('tier_' + tier),
                turningPoint: turning,
                insights: insights,
                questions: [this._t('q1'), this._t('q2'), this._t('q3')]
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var self = this;
            var li = function(a) { return (a || []).map(function(x) { return '<li>' + x + '</li>'; }).join(''); };
            return '<div class="completion-message carbon-sim-debrief p-4">'
                + '<div class="carbon-sim-debrief-tier">' + (s.performanceLabel || '') + ' · ' + this._t('deb_score', { s: s.finalScore }) + '</div>'
                + '<p>' + this._t('tierdesc_' + (s.performance || 'stranded')) + '</p>'
                + '<p>' + this._t('deb_kpis', { e: this._num(s.finalEmissions, 0), t: this._num(s.sbtiTarget, 0), traj: s.trajectoryScore, ab: s.abatementProgress, bill: this._usd(s.totalCarbonCost), q: s.creditQualityAvg }) + '</p>'
                + '<h4>' + this._t('deb_turning') + '</h4><p>' + (s.turningPoint || '') + '</p>'
                + '<h4>' + this._t('deb_insights') + '</h4><ul>' + li(s.insights) + '</ul>'
                + '<h4>' + this._t('deb_questions') + '</h4><ol>' + li(s.questions) + '</ol>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.trajectoryScore < 40) return window.mySimulation.t('hint_trajectory_critical');
            if (results.trajectoryScore < 60) return window.mySimulation.t('hint_trajectory_low');
            if (results.compliance && results.compliance !== 'green') return window.mySimulation.t('hint_compliance_risk');
            if (results.abatementPct < 20 && state.currentPeriod >= 3) return window.mySimulation.t('hint_abatement_low');
            if (results.creditQuality < 50) return window.mySimulation.t('hint_quality_low');
            if (results.cbamCost > 8) return window.mySimulation.t('hint_cbam_high');
            return null;
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.year', label: 'Year', i18nKey: 'col_year' },
                { key: 'results.emissions', label: 'Emissions', i18nKey: 'col_emissions', formatter: function(v) { return self._num(v, 0); } },
