                { key: 'results.abatementSpent', label: 'Abatement $M', i18nKey: 'col_abatement_cost', formatter: function(v) { return '$' + self._num(v, 1); } },
                { key: 'results.cbamCost', label: 'CBAM $M', i18nKey: 'col_cbam', formatter: function(v) { return '$' + self._num(v, 1); } },
                { key: 'results.totalRoundCost', label: 'Total Cost $M', i18nKey: 'col_total_cost', formatter: function(v) { return '$' + self._num(v, 1); } },
                { key: 'results.trajectoryScore', label: 'Trajectory', i18nKey: 'col_trajectory' },
