    document.addEventListener('DOMContentLoaded', function() {
        var adapter = new CarbonTradingAdapter();
        window.mySimulation = new USF.SimulationFramework();
        var repaint = function () {
            setTimeout(function () { try { adapter._tb = null; adapter._updateBriefing(window.mySimulation.state); } catch (e) {} }, 0);
        };
        // undo rewinds the state and the counter but not what the sim itself wrote
        var undoBtn = document.getElementById('undoBtn');
        if (undoBtn) undoBtn.addEventListener('click', repaint);
        document.addEventListener('express:langchanged', repaint);
        var ids = ['abatementBudgetInput', 'allowanceInput', 'reddInput', 'biogasInput', 'cookstoveInput', 'strategicSelect'];
        ids.forEach(function (id) {
            var el = document.getElementById(id);
            if (!el) return;
            el.addEventListener('input', function () { try { adapter._renderPlan(); } catch (e) {} });
            el.addEventListener('change', function () { try { adapter._renderPlan(); } catch (e) {} });
        });
        window.mySimulation.initialize(adapter, {
            simulationType: 'carbon_trading_climate_finance',
            maxPeriods: 6,
            autoSaveInterval: 30000
        });
        try { adapter._updateBriefing(window.mySimulation.state); } catch (e) {}
    });

})();
